class Res(object):
    def __init__(self, **kw):
        super(Res, self).__init__(**kw)

    def __str__(self):
        if self.data:
            print("%s: %d" % (self.type, self.data))
        else:
            print("%s: %s" % (self.type, self.info))

    def return_none(self):
        print("None type.")

    def return_class(self, cls):
        print(type(cls))

    def return_data(self, data):
        print(type(data))

    def return_str(self, s):
        print(type(s))

    def return_int(self, i):
        print(type(i))

    def return_float(self, f):
        print(type(f))

    def return_bytes(self, bytes_obj):
        print(type(bytes_obj))

    def return_tup(self, tup):
