        print(type(frozenset_obj))

    def return_ellipsis(self, ellipsis_obj):
        print(type(ellipsis_obj))

    def return_complex(self, complex_obj):
        print(type(complex_obj))

    def return_bool(self, bool_obj):
        print(type(bool_obj))

    def return_file(self, file_obj):
        print(type(file_obj))

    def return_methodobj(self, method_obj):
        print(type(method_obj))

    def return_sequence(self, sequence_obj):
        print(type(sequence_obj))

    def return_generator(self, generator_obj):
        print(type(generator_obj))

    def return_coroutine(self, coroutine_obj):
        print(type(coroutine_obj))

    def return_asyncgen(self, asyncgen_obj):
        print(type(asyncgen_obj))

    def return_property(self, property_obj):
        print(type(property_obj))

    def return_exception(self, exception_obj):
        print(type(exception_obj))

    def return_methods(self, methods_obj):
        for m in methods_obj:
            print(type(m))


