  INTERFACE
    FUNCTION mean_stddev(x, mean, std_dev)
      INTEGER, DIMENSION(:), INTENT(IN) :: x
      REAL, INTENT(OUT) :: mean
      REAL, INTENT(OUT) :: std_dev
    END FUNCTION mean_stddev
  END INTERFACE

CONTAINS

  !Function mean_stddev
  FUNCTION mean_stddev(x, mean, std_dev) RESULT(mean_stddev_result)
    INTEGER, DIMENSION(:), INTENT(IN) :: x
    REAL, INTENT(OUT) :: mean
    REAL, INTENT(OUT) :: std_dev
    INTEGER :: i, n
    REAL :: ss, sum

    !Mean
    sum = 0.0
    DO i = LBOUND(x, 1), UBOUND(x, 1)
      sum = sum + x(i)
    ENDDO

    mean = sum / SIZE(x)

    !Sample Standard Deviation
    n = SIZE(x)
    ss = 0.0
    DO i = LBOUND(x, 1), UBOUND(x, 1)
      ss = ss + (x(i) - mean) ** 2
    ENDDO

    std_dev = SQRT(ss / (n - 1))

  ENDFUNCTION mean_stddev

END MODULE mean_stddev

