import matplotlib.pyplot as plt

# Specify input TIFF
input_tif = 'multi_page.tif'

# Specify desired output filename
output_fig = 'per_page_histograms.pdf'

# Read TIFF, note plugin behavior
pages = io.imread(input_tif)
num_pages = len(pages)
print(f'Input TIFF has {num_pages} pages')

# Initialize figure
fig, ax = plt.subplots(nrows=num_pages, figsize=(10, 10*num_pages))

# Iterate through pages
for i, page in enumerate(pages):
    # Compute histogram
    hist = plt.hist(page.ravel(), bins=256)

    # Plot histogram
    ax[i].set_title(f'Page {i+1}')
    ax[i].set_ylabel('Count')
    ax[i].set_xlabel('Intensity')

    ax[i].plot(hist[1][:-1], hist[0])

# Save figure
plt.savefig(output_fig, bbox_inches='tight')
print(f'File {output_fig} saved')

# Display figure
